import{_ as e,o as i,c as a,ag as o}from"./chunks/framework.BYYsWsaA.js";const s=JSON.parse('{"title":"LLM 接口预留说明","description":"","frontmatter":{},"headers":[],"relativePath":"llm-integration-interface.md","filePath":"llm-integration-interface.md","lastUpdated":1773595350000}'),t={name:"llm-integration-interface.md"};function r(d,l,c,n,h,p){return i(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="llm-接口预留说明" tabindex="-1">LLM 接口预留说明 <a class="header-anchor" href="#llm-接口预留说明" aria-label="Permalink to &quot;LLM 接口预留说明&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>当前系统先完成传统规则分析与风险评分，但为后续接入 AI 解读能力预留统一接口。</p><p>设计原则：</p><ul><li>不影响现有 API 主链路</li><li>默认不开启外部大模型调用</li><li>没有 API Key 时也能返回可用的上下文和 Prompt</li></ul><h2 id="当前实现" tabindex="-1">当前实现 <a class="header-anchor" href="#当前实现" aria-label="Permalink to &quot;当前实现&quot;">​</a></h2><p>核心文件：</p><ul><li><code>backend/monitoring/llm.py</code></li><li><code>backend/monitoring/views.py</code></li><li><code>backend/monitoring/urls.py</code></li></ul><p>接口：</p><ul><li><code>POST /api/v1/measurements/{measurement_id}/llm-insight</code></li></ul><h2 id="接口行为" tabindex="-1">接口行为 <a class="header-anchor" href="#接口行为" aria-label="Permalink to &quot;接口行为&quot;">​</a></h2><h3 id="默认状态" tabindex="-1">默认状态 <a class="header-anchor" href="#默认状态" aria-label="Permalink to &quot;默认状态&quot;">​</a></h3><p>如果没有配置外部模型服务，接口会返回：</p><ul><li><code>available: false</code></li><li><code>prompt</code></li><li><code>context</code></li><li><code>provider</code></li><li><code>model</code></li></ul><p>这样前端或后续服务可以先看到：</p><ul><li>传给 LLM 的上下文是什么</li><li>Prompt 是怎么组织的</li><li>后续需要什么配置才能真正调用模型</li></ul><h3 id="配置后状态" tabindex="-1">配置后状态 <a class="header-anchor" href="#配置后状态" aria-label="Permalink to &quot;配置后状态&quot;">​</a></h3><p>如果配置了兼容 OpenAI Chat Completions 的接口，后端会尝试真实调用，并返回：</p><ul><li><code>available: true</code></li><li><code>content</code></li><li><code>context</code></li><li><code>prompt</code></li></ul><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><p>当前支持以下变量：</p><ul><li><code>LLM_PROVIDER</code></li><li><code>LLM_API_BASE_URL</code></li><li><code>LLM_API_KEY</code></li><li><code>LLM_MODEL</code></li><li><code>LLM_TIMEOUT</code></li></ul><p>推荐含义：</p><ul><li><code>LLM_PROVIDER=openai_compatible</code></li><li><code>LLM_API_BASE_URL=https://your-llm-service.example.com/v1</code></li><li><code>LLM_MODEL=gpt-4o-mini</code></li></ul><p>如果不配置，系统默认为：</p><ul><li><code>LLM_PROVIDER=disabled</code></li></ul><h2 id="为什么先保留接口而不直接强依赖-llm" tabindex="-1">为什么先保留接口而不直接强依赖 LLM <a class="header-anchor" href="#为什么先保留接口而不直接强依赖-llm" aria-label="Permalink to &quot;为什么先保留接口而不直接强依赖 LLM&quot;">​</a></h2><p>原因有三点：</p><h3 id="_1-先保证核心分析可控" tabindex="-1">1. 先保证核心分析可控 <a class="header-anchor" href="#_1-先保证核心分析可控" aria-label="Permalink to &quot;1. 先保证核心分析可控&quot;">​</a></h3><p>当前规则分析、时间窗统计、个人基线偏移，是系统必须稳定可解释的核心逻辑。</p><h3 id="_2-大模型适合做-解释层-而不是-主判定层" tabindex="-1">2. 大模型适合做“解释层”而不是“主判定层” <a class="header-anchor" href="#_2-大模型适合做-解释层-而不是-主判定层" aria-label="Permalink to &quot;2. 大模型适合做“解释层”而不是“主判定层”&quot;">​</a></h3><p>房颤风险判断目前应以结构化规则/统计结果为主，LLM 更适合做：</p><ul><li>风险解读</li><li>面向用户的中文说明</li><li>告警内容润色</li><li>健康建议生成</li></ul><h3 id="_3-接入方式以后可能变化" tabindex="-1">3. 接入方式以后可能变化 <a class="header-anchor" href="#_3-接入方式以后可能变化" aria-label="Permalink to &quot;3. 接入方式以后可能变化&quot;">​</a></h3><p>后续可以接：</p><ul><li>OpenAI 兼容接口</li><li>本地部署模型</li><li>医疗专用问答模型</li></ul><p>因此现在先把接口层抽出来，比把模型调用写死在主分析逻辑里更稳。</p><h2 id="推荐使用方式" tabindex="-1">推荐使用方式 <a class="header-anchor" href="#推荐使用方式" aria-label="Permalink to &quot;推荐使用方式&quot;">​</a></h2><p>建议未来把 LLM 作为“辅助解读模块”，而不是直接替代规则分析：</p><ol><li>先由后端规则分析输出结构化结果</li><li>再把结构化结果传给 LLM</li><li>由 LLM 输出更适合用户阅读的中文解释</li></ol><p>推荐输出结构：</p><ul><li>风险结论</li><li>触发原因</li><li>建议动作</li><li>注意事项</li></ul><h2 id="当前接口的价值" tabindex="-1">当前接口的价值 <a class="header-anchor" href="#当前接口的价值" aria-label="Permalink to &quot;当前接口的价值&quot;">​</a></h2><p>虽然现在默认不调用真实大模型，但这个接口已经具备：</p><ul><li>稳定的输入输出形态</li><li>可调试的 Prompt</li><li>后续可直接接入 AI 服务的扩展位</li></ul><p>这意味着后续接入 AI 时，不需要再改动主分析链路，只需要补环境变量和服务地址即可。</p>',46)])])}const m=e(t,[["render",r]]);export{s as __pageData,m as default};
